households = {
    'RT_A': {'air': 0, 'sanitasi': 0, 'luas': 1, 'durabilitas': 0},
    'RT_B': {'air': 1, 'sanitasi': 1, 'luas': 0, 'durabilitas': 0},
    'RT_C': {'air': 0, 'sanitasi': 0, 'luas': 1, 'durabilitas': 1},
    'RT_D': {'air': 0, 'sanitasi': 0, 'luas': 0, 'durabilitas': 0},
}
weights = {'air': 15, 'sanitasi': 15, 'luas': 35, 'durabilitas': 35}

for rt, flags in households.items():
    score = sum(flags[dim] * weights[dim] for dim in weights)
    is_kumuh = score > 35
    print(f'{rt}: Skor={score}%, Kumuh={is_kumuh}')
